    opponents = observation.get('opponents', [])
    territory = observation.get('territory', {})

    # Helper to determine if an opponent is nearby
    def is_opponent_nearby(pos, threshold=1):
        for opp in opponents:
            ox, oy = opp.get('position', (0, 0))
            if abs(ox - pos[0]) <= threshold and abs(oy - pos[1]) <= threshold:
                return True
        return False

