            move_x = 0 if dx == 0 else (1 if dx >0 else -1)
            move_y = 0 if dy == 0 else (1 if dy >0 else -1)
            return [move_x, move_y]

    # For territory control, move towards unclaimed territory
    # Find direction towards maximum unclaimed area
    # Simplified: attempt to move randomly within grid to spread out
    # If territory info is present, move toward unclaimed
    # Otherwise, move randomly
    if territory:
        # Check simple heuristics: move towards unclaimed territory
        unclaimed_dirs = []
