                unclaimed_dirs.append((dx, dy))
        if unclaimed_dirs:
            return list(unclaimed_dirs[0])

    # Default move: stay still or move randomly
    # To keep it deterministic, pick a preferred direction
    # For simplicity, move east until blocked (no obstacle info), else go south
    return [1, 0]  # move east as default move

